(()=>{
const children=['books','board-games','steam'];
// Room doors are the only entrances offered by the interface.
function entrances(){document.querySelectorAll('a[href]').forEach(a=>{if(!children.includes(a.hash.slice(1))||a.closest('.room-doors'))return;if(a.closest('.header nav,.chapter-dock,.passport-stamps')){a.hidden=true;return;}a.href='#living-room';if(a.hasAttribute('aria-label'))a.setAttribute('aria-label','Back to the living room');if(a.closest('.page-sequence'))a.querySelector('strong')&&(a.querySelector('strong').textContent='Living Room');});}
entrances();document.addEventListener('portfolio:pagechange',()=>{entrances();const id=document.querySelector('.page.active')?.id;const nav=document.querySelector('.page-sequence');if(id==='living-room')nav.innerHTML='<a href="#playground"><span>Back</span><strong>Playground</strong></a><a href="#contact"><span>Next</span><strong>Contact</strong></a>';if(children.includes(id))nav.innerHTML='<a href="#living-room"><span>←</span><strong>Back to the living room</strong></a>';});
const lobby=document.querySelector('.room-doors');const lounge=document.createElement('div');lounge.className='lobby-furniture';lounge.setAttribute('aria-hidden','true');lounge.innerHTML='<div class="lobby-rug"></div><div class="lobby-sofa"><i></i><i></i></div><div class="lobby-table"><i></i></div><div class="lobby-plant">❧</div>';lobby.after(lounge);
const study=document.querySelector('.reading-room');const shelf=document.createElement('div');shelf.className='study-shelves';const first=study.querySelector('.reading-book');shelf.append(first,...document.querySelectorAll('.extra-books .reading-book'));document.querySelector('.extra-books').remove();study.prepend(shelf);study.querySelector('.reading-note').classList.add('study-desk');
const cabinet=document.querySelector('#board-collection');cabinet.classList.add('glass-cabinet');cabinet.querySelector('.room-lounge')?.remove();
const station=document.createElement('div');station.className='gaming-station';station.setAttribute('aria-hidden','true');station.innerHTML='<div class="gaming-monitor"><span>PLAYER ONE</span><strong>Choose your next world.</strong><i>● ● ●</i></div><div class="gaming-tower"><i></i><i></i></div><div class="gaming-desk"></div><div class="gaming-chair"></div>';document.querySelector('#steam-collection').before(station);
const icons=['car','cyber','car','cyber','knight','wizard','ball','knight','animal','pc','hero','animal','knight','knight','hero','soldier','hero','car','soldier','soldier','knight','knight','soldier','car'];
const paths={car:'M18 66h84v23H18z M32 66l12-23h34l17 23 M37 90v8m48-8v8',cyber:'M43 24h34v33H43z M30 63h60v37H30z M47 37h26 M60 16V8 M25 70H13m82 0h12',knight:'M40 20h40v36H40z M30 65l30-10 30 10-10 40H40z M60 24v25 M16 30v70 M8 40h16',wizard:'M33 46L60 5l27 41z M43 48v18h34V48 M60 63l-30 42h60z M96 35v65',ball:'M60 20a40 40 0 1 0 0 80 40 40 0 1 0 0-80 M60 40l20 15-8 24H48l-8-24z M60 20v20 M20 60l20-5 M100 60l-20-5',animal:'M27 50l10-28 17 16h28l14 20-12 35H36z M45 60h2m28 0h2 M54 77h15',pc:'M30 15h60v90H30z M60 30a12 12 0 1 0 0 24 12 12 0 1 0 0-24 M60 64a12 12 0 1 0 0 24 12 12 0 1 0 0-24',hero:'M40 45V18l12 10h16l12-10v27L60 60z M60 60L24 100h72z',soldier:'M33 40q0-30 27-30t27 30z M43 45v18h34V45 M30 72l30-10 30 10v30H30z'};
document.querySelectorAll('#steam-collection>a').forEach((a,i)=>{const figure=document.createElement('div');figure.className='game-figurine';figure.setAttribute('aria-hidden','true');figure.innerHTML='<svg viewBox="0 0 120 120" fill="none"><ellipse cx="60" cy="110" rx="44" ry="7"/><path d="'+paths[icons[i]||(/car|wreck|thunder/i.test(a.textContent)?'car':/coaster|hunter/i.test(a.textContent)?'animal':'hero')]+'"/></svg>';a.querySelector('h2').before(figure);});
})();
